# Cloud Architecture Code Examples

Here are practical code examples demonstrating secure, scalable cloud architecture patterns:

## 1. Serverless Function with Defense-in-Depth (Python)

```python
import boto3
import json
from datetime import datetime
from typing import Dict, Any

class SecureServerlessFunction:
    """Secure serverless function with proper error handling and logging"""

    def __init__(self):
        self.sqs = boto3.client('sqs')
        self.logs = boto3.client('logs')

    def process_event(self, event: Dict[str, Any]) -> Dict[str, Any]:
        """Process incoming events with validation and sanitization"""

        # Input validation
        if not self._validate_input(event):
            return self._create_error_response("Invalid input")

        try:
            # Process business logic
            result = self._process_business_logic(event)

            # Log success
            self._log_event("success", event, result)

            return {
                "statusCode": 200,
                "body": json.dumps(result),
                "headers": {"Content-Type": "application/json"}
            }

        except Exception as e:
            # Log error (without sensitive data)
            self._log_event("error", event, str(e))
            return self._create_error_response(str(e))

    def _validate_input(self, event: Dict[str, Any]) -> bool:
        """Validate and sanitize input"""
        if not isinstance(event, dict):
            return False

        # Sanitize inputs
        for key in event:
            if isinstance(event[key], str):
                event[key] = event[key].strip()

        return True

    def _create_error_response(self, message: str) -> Dict[str, Any]:
        """Create standardized error response"""
        return {
            "statusCode": 500,
            "body": json.dumps({"error": message}),
            "headers": {"Content-Type": "application/json"}
        }
```

