# Caching Strategy with Proper Cache Invalidation for Dynamic Content

Implementing effective caching with proper invalidation is critical for maintaining data consistency while maximizing performance. Here's a comprehensive approach:

## Core Caching Strategies

### 1. **Time-Based Expiration (TTL)**
```python
from functools import lru_cache
import time

@lru_cache(maxsize=100)
def get_user_profile(user_id):
    # Cache expires automatically after TTL
    return fetch_from_db(user_id)
```

**Pros:** Simple to implement, automatic cleanup  
**Cons:** May serve stale data during updates

### 2. **Version-Based Caching**
```python
from cachetools import TTLCache, cached

cache = TTLCache(maxsize=1000, ttl=300)

@cached(cache=lambda d: {k: v for k, v in cache.items()})
def get_product(product_id):
    # Include version in cache key
    return fetch_with_version(product_id)
```

### 3. **Cache-Aside Pattern**
```python
class CacheManager:
    def __init__(self, redis_client):
        self.redis = redis_client

    def get(self, key):
        cached = self.redis.get(key)
        if cached:
            return json.loads(cached)
        return None

    def set(self, key, value, ttl=300):
        self.redis.setex(key, ttl, json.dumps(value))

    def invalidate(self, pattern):
        # Invalidate by pattern for dynamic content
        keys = self.redis.keys(pattern)
        if keys:
            self.redis.delete(*keys)
```

## Cache Invalidation Techniques

### **1. Write-Through with Versioning**
```python
class VersionedCache:
    def __init__(self, redis_client):
        self.redis = redis_client

    def get(self, key):
        data = self.redis.get(key)
        if not data:
            return None
        version = json.loads(data)['version']
        return json.loads(data)

    def set(self, key, value, ttl=300):
        # Increment version and update cache
        current_version = self.redis.hget(f"{key}:version", "v") or 0
        new_version = int(current_version) + 1

        data = {
            'value': value,
            'version': new_version,
            'timestamp': time.time()
        }

        self.redis.setex(key, ttl, json.dumps(data))
        self.redis.hset(f"{key}:version", "v", str(new_version))

    def invalidate(self, key):
        # Invalidate specific key and version tracking
        self.redis.delete(key)
        self.redis.delete(f"{key}:version")
```

### **2. Event-Driven Invalidation**
```python
import redis
from datetime import datetime

class EventDrivenCache:
    def __init__(self, redis_client):
        self.redis = redis_client

    def invalidate_by_event(self, event_type, resource_id):
        """Invalidate cache when specific events occur"""
        # Publish invalidation event
        self.redis.publish(
            f"invalidation:{event_type}",
            json.dumps({
                'resource_id': resource_id,
                'timestamp': datetime.utcnow().isoformat()
            })
        )

    def subscribe_to_invalidation(self, pattern):
        """Subscribe to invalidation events"""
        pubsub = self.redis.pubsub()
        pubsub.subscribe(f"invalidation:*")

        for message in pubsub.listen():
            if 'type' in message:
                event_type = message['data'].get('event_type')
                resource_id = message['data'].get('resource_id')

                # Invalidate matching cache entries
                keys = self.redis.keys(f"cache:{event_type}:*")
                for key in keys:
                    if resource_id in key:
                        self.redis.delete(key)
```

